panel 1

node greeting : conduit.std/literal {
    value = "Hello from the Tour.\n"
}
node output : conduit.std/stdout

cord greeting.out -> output.in {
    capacity = 1
    max_value_bytes = 1024
    max_queued_bytes = 1024
    low_watermark = 0
    high_watermark = 1
    pressure = block
}

